#include <bits/stdc++.h>
#define fi first
#define se second
using namespace std;

const int MAXN = 5500;
const long long INF = 1e9 + 7;

int n, m, k, c, d;
int start, end_node, total_flow = 0, source = MAXN - 2, sink = MAXN - 1, flow_count = 0, parent[MAXN];
long long total_cost = 0, dist[MAXN];
priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;

struct Edge {
    int v, c;
    int idx, cap;
};
vector<Edge> adj[MAXN];

void add_edge(int u, int v, int cst, int cap) {
    int szU = adj[u].size(), szV = adj[v].size();
    adj[u].push_back({v, cst, szV, cap});
    adj[v].push_back({u, -cst, szU, 0});
}

void shortest_path() {
    fill(dist, dist + MAXN, INF);
    pq.push({dist[source] = 0, source});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto &e : adj[u]) {
            if (e.cap > 0 && dist[e.v] > d + e.c) {
                parent[e.v] = e.idx;
                dist[e.v] = d + e.c;
                pq.push({dist[e.v], e.v});
            }
        }
    }
}

void update_flow() {
    int flow_add = k, v = end_node;
    while (v != source) {
        int u = adj[v][parent[v]].v;
        int ind = adj[v][parent[v]].idx;
        flow_add = min(flow_add, adj[u][ind].cap);
        v = u;
    }
    total_flow += flow_add;
    total_cost += (long long)flow_add * dist[end_node];
    v = end_node;
    while (v != source) {
        int u = adj[v][parent[v]].v;
        int ind = adj[v][parent[v]].idx;
        adj[v][parent[v]].cap += flow_add;
        adj[u][ind].cap -= flow_add;
        v = u;
    }
}

int node_id(int u, int t) {
    return u + t * n;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> k >> c >> d;
    start = n + k;
    for (int i = 0; i < k; i++) {
        cin >> u;
        add_edge(source, node_id(u, 0), 0, 1);
    }
    for (int i = 0; i <= n + k; i++)
        add_edge(node_id(1, i), sink, c * i, k);
    for (int i = 1; i <= n; i++)
        for (int j = 0; j < n + k; j++)
            add_edge(node_id(i, j), node_id(i, j + 1), 0, k);
    for (int i = 0; i < m; i++) {
        cin >> u >> v;
        for (int j = 0; j < k; j++) {
            for (int l = 0; l < n + k; l++) {
                add_edge(node_id(u, l), node_id(v, l + 1), d * (2 * j + 1), 1);
                add_edge(node_id(v, l), node_id(u, l + 1), d * (2 * j + 1), 1);
            }
        }
    }
    while (total_flow < k) {
        shortest_path();
        update_flow();
    }
    cout << total_cost;
}
